@@ -8,6 +8,24 @@ import { serialize, type Index } from './serialize.js';

-export function saveIndex(file: string, index: Index): void {
-  writeFileSync(file, serialize(index));
+/** Crash-safe save: serialize to a temp file, fsync, then atomically rename
+ *  over the target. A failure at any step leaves the previous index file
+ *  intact (the rename is all-or-nothing), and the temp file is removed. */
+export function saveIndex(file: string, index: Index): void {
+  const tmp = `${file}.tmp-${process.pid}`;
+  try {
+    const fd = openSync(tmp, 'w');
+    try {
+      writeSync(fd, serialize(index));
+      fsyncSync(fd);
+    } finally {
+      closeSync(fd);
+    }
+    renameSync(tmp, file); // atomic on POSIX: readers see old or new, never a torn write
+  } catch (err) {
+    rmSync(tmp, { force: true });
+    throw new IndexWriteError(file, err);
+  }
 }
